import{_ as t,o,c as a,a2 as r}from"./chunks/framework.D66Xq0Kv.js";const n="/assets/glb-large.D8LeMsuY.png",g=JSON.parse('{"title":"3D Models","description":"","frontmatter":{},"headers":[],"relativePath":"3dmodels.md","filePath":"3dmodels.md"}'),s={name:"3dmodels.md"};function i(l,e,d,h,u,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="_3d-models" tabindex="-1">3D Models <a class="header-anchor" href="#_3d-models" aria-label="Permalink to &quot;3D Models&quot;">​</a></h1><p>Elevator supports two different 3D viewers, the <a href="https://3dhop.net" target="_blank" rel="noreferrer">3DHop</a> viewer from the <a href="http://vcg.isti.cnr.it" target="_blank" rel="noreferrer">Visual Computing Lab</a> at CNR-ISTI, as well as <a href="https://smithsonian.github.io/dpo-voyager/" target="_blank" rel="noreferrer">Voyager</a> from the Smithsonian. 3DHop is the default, but Voyager can be enabled on an instance-by-instance basis in the Instance Settings.</p><p>The default mode for Voyager is a 3D model viewer with some basic tools for sliding and measurement. However, Voyager supports much more sophisticated annotation and tour-building. Currently, using these steps with Elevator requires a few extra steps. Eventually we hope to streamline these.</p><h2 id="model-prep" tabindex="-1">Model Prep <a class="header-anchor" href="#model-prep" aria-label="Permalink to &quot;Model Prep&quot;">​</a></h2><p>Begin by uploading your model into an Elevator asset. In general, models should be zip files container OBJ, MTL and texture files.</p><p>Once Elevator processes your model (this can take a few minutes) you should be able to see a basic 3D view on the asset page.</p><p>Now, use the &quot;download derivatives&quot; button and download the GLB-Large file.</p><p><img src="'+n+'" alt="&quot;GLB Large Download&quot;"></p><h2 id="tour-annotation-creation" tabindex="-1">Tour/Annotation Creation <a class="header-anchor" href="#tour-annotation-creation" aria-label="Permalink to &quot;Tour/Annotation Creation&quot;">​</a></h2><p>In your browser, load the <a href="https://3d.si.edu/voyager-story-standalone" target="_blank" rel="noreferrer">Voyager Story Standalone</a> application. This is the tool for building tours. Drag and drop your GLB file into the Story tool. When it prompts you for a derivative quality, select &quot;High&quot;.</p><p>Now, add any tours, annotations, or other features to your model. Currently, the &quot;articles&quot; feature isn&#39;t supported, but we&#39;re looking at options for that going forward. Instead, you can link to other websites to share more content - you can use the &quot;extended&quot; annotation type and then put links in the &quot;Lead&quot; section, using standard HTML:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;a href=&quot;http://www.whyshouldivisit.com&quot;&gt;Why Should I Visit?&lt;/a&gt;</span></span></code></pre></div><p>When you&#39;ve completed your work, click the download button in the upper right to download the finished scene. That will download a zip file.</p><h2 id="adding-the-scene-to-elevator" tabindex="-1">Adding the Scene to Elevator <a class="header-anchor" href="#adding-the-scene-to-elevator" aria-label="Permalink to &quot;Adding the Scene to Elevator&quot;">​</a></h2><p>Go back into the Edit view for your asset. Unzip the file that was downloaded by Voyager Story. Use the &quot;Load from File&quot; button in Elevator to select the SVX file from the Voyager Story and load that into your Elevator asset.</p>',15)])])}const m=t(s,[["render",i]]);export{g as __pageData,m as default};
